import{_ as e,C as l,c as t,o as r,j as i,G as a,b as n,a0 as s,a as o,w as d,a1 as u}from"./chunks/framework.DKRgXLPU.js";const k=JSON.parse('{"title":"At være en god holdspiller","description":"","frontmatter":{},"headers":[],"relativePath":"da/education/team-player/index.md","filePath":"da/education/team-player/index.md"}');const m=e({name:"da/education/team-player/index.md"},[["render",function(e,k,m,g,h,f){const p=l("AdBanner"),v=l("Mermaid"),b=l("AdInArticle");return r(),t("div",null,[k[1]||(k[1]=i("h1",{id:"at-være-en-god-holdspiller",tabindex:"-1"},[o("At være en god holdspiller "),i("a",{class:"header-anchor",href:"#at-være-en-god-holdspiller","aria-label":'Permalink to "At være en god holdspiller"'},"​")],-1)),a(p),k[2]||(k[2]=i("p",null,"Pétanque spilles ofte i hold - double (dublettes) eller triples (triplettes). Individuelle færdigheder betyder noget, men holddynamik kan være afgørende for resultaterne. De bedste hold er ikke altid de dygtigste - det er dem, der arbejder bedst sammen.",-1)),k[3]||(k[3]=i("div",{class:"tip custom-block"},[i("p",{class:"custom-block-title"},"Den store idé"),i("p",null,[i("strong",null,"De bedste hold er ikke altid de dygtigste - det er dem, der fungerer bedst sammen."),o(" At være ydmyg, sulten og følelsesmæssigt intelligent gør dig til en god holdkammerat.")])],-1)),(r(),n(u,null,{default:d(()=>[a(v,{id:"mermaid-13",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BFantastisk%20holdkammerat%5D%20--%3E%20B%5BYdmyg%5D%0A%20%20%20%20A%20--%3E%20C%5BSulten%5D%0A%20%20%20%20A%20--%3E%20D%5BSmart%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BHoldets%20succes%5D%0A%20%20%20%20C%20--%3E%20E%0A%20%20%20%20D%20--%3E%20E%0A%0A%20%20%20%20E%20--%3E%20F%5BMesterskabspr%C3%A6station%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23fff4e1%0A%20%20%20%20style%20D%20fill%3A%23f3e5f5%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:d(()=>[...k[0]||(k[0]=[o(" Loading... ",-1)])]),_:1})),k[4]||(k[4]=s('<h2 id="hvad-gør-en-god-holdkammerat" tabindex="-1">Hvad gør en god holdkammerat? <a class="header-anchor" href="#hvad-gør-en-god-holdkammerat" aria-label="Permalink to &quot;Hvad gør en god holdkammerat?&quot;">​</a></h2><p>Forskning og erfaring peger på tre nøglekvaliteter:</p><h3 id="_1-ydmyg" tabindex="-1">1. Ydmyg <a class="header-anchor" href="#_1-ydmyg" aria-label="Permalink to &quot;1. Ydmyg&quot;">​</a></h3><ul><li>Prioriterer holdets succes frem for personlig ære</li><li>Anerkender andres bidrag</li><li>Indrømmer fejl uden undskyldninger</li><li>Åben for feedback og læring</li><li>Behøver ikke at være stjernen</li></ul><h3 id="_2-sulten" tabindex="-1">2. Sulten <a class="header-anchor" href="#_2-sulten" aria-label="Permalink to &quot;2. Sulten&quot;">​</a></h3><ul><li>Selvmotiveret og drevet</li><li>Gør arbejdet uden at blive bedt om det</li><li>Altid på udkig efter forbedring</li><li>Bringer energi til holdet</li><li>Løfter sig ikke på talent</li></ul><h3 id="_3-smart-følelsesmæssigt" tabindex="-1">3. Smart (følelsesmæssigt) <a class="header-anchor" href="#_3-smart-følelsesmæssigt" aria-label="Permalink to &quot;3. Smart (følelsesmæssigt)&quot;">​</a></h3><ul><li>Læser situationer og personer godt</li><li>Ved hvornår man skal tale og hvornår man skal lytte</li><li>Håndterer sine egne følelser</li><li>Støtter holdkammeraterne passende</li><li>Håndterer konflikter konstruktivt</li></ul><h2 id="grundlaget-for-teamets-succes" tabindex="-1">Grundlaget for teamets succes <a class="header-anchor" href="#grundlaget-for-teamets-succes" aria-label="Permalink to &quot;Grundlaget for teamets succes&quot;">​</a></h2><h3 id="fælles-mal-og-vision" tabindex="-1">Fælles mål og vision <a class="header-anchor" href="#fælles-mal-og-vision" aria-label="Permalink to &quot;Fælles mål og vision&quot;">​</a></h3><p>Stærke hold har:</p><ul><li>Klare, aftalte mål</li><li>Individuelle mål i overensstemmelse med holdets mål</li><li>Fælles forståelse af, hvad succes ser ud</li><li>Forpligtelse til den kollektive mission</li></ul><p><strong>Spørgsmål til diskussion med dit team:</strong></p><ul><li>Hvad prøver vi at opnå sammen?</li><li>Hvordan ser succes ud for os?</li><li>Hvordan understøtter vores individuelle mål holdet?</li></ul><h3 id="effektiv-kommunikation" tabindex="-1">Effektiv kommunikation <a class="header-anchor" href="#effektiv-kommunikation" aria-label="Permalink to &quot;Effektiv kommunikation&quot;">​</a></h3><p>Kommunikation er livsnerven i et teams præstation.</p><p><strong>God teamkommunikation:</strong></p><ul><li>Åben og ærlig</li><li>Respektfuld, selv i uenighed</li><li>Klar og specifik</li><li>Tovejs (tale OG lytte)</li><li>Rettidig (rigtig information på rette tidspunkt)</li></ul>',18)),a(b),k[5]||(k[5]=s('<p><strong>Under kampene:</strong></p><ul><li>Diskuter strategi før hver omgang</li><li>Del observationer om terræn, modstandere</li><li>Koordinér hvem der kaster hvornår</li><li>Støt hinanden efter kast (gode eller dårlige)</li></ul><h3 id="tillid-og-respekt" tabindex="-1">Tillid og respekt <a class="header-anchor" href="#tillid-og-respekt" aria-label="Permalink to &quot;Tillid og respekt&quot;">​</a></h3><p>Uden tillid falder hold fra hinanden under pres.</p><p><strong>Opbygning af tillid:</strong></p><ul><li>Vær pålidelig (gør hvad du siger)</li><li>Vær kompetent (udfør dit arbejde godt)</li><li>Vær ærlig (selv når det er svært)</li><li>Vis sårbarhed (indrøm dine udfordringer)</li><li>Støt andre konsekvent</li></ul><p><strong>Viser respekt:</strong></p><ul><li>Værdsæt hver enkelt persons bidrag</li><li>Lyt til forskellige perspektiver</li><li>Anerkend indsatsen, ikke kun resultaterne</li><li>Betragt alles rolle som vigtig</li></ul><h3 id="klare-roller" tabindex="-1">Klare roller <a class="header-anchor" href="#klare-roller" aria-label="Permalink to &quot;Klare roller&quot;">​</a></h3><p>Alle burde forstå:</p><ul><li>Deres primære ansvarsområder</li><li>Hvordan de bidrager til holdet</li><li>Hvad andre regner med dem for</li><li>Hvornår skal man træde frem, og hvornår skal man træde tilbage</li></ul><p><strong>I tredobbelte:</strong></p><table tabindex="0"><thead><tr><th>Rolle</th><th>Primært fokus</th><th>Nøglekvaliteter</th></tr></thead><tbody><tr><td>Peger</td><td>Placer boules nær målkuglen</td><td>Præcision, konsistens</td></tr><tr><td>Midt</td><td>Tilpas dig til situationen</td><td>Alsidighed, læsespil</td></tr><tr><td>Skytte</td><td>Fjern modstanderens kugler</td><td>Præcision under pres</td></tr></tbody></table><p>Roller kan være fleksible, men klarhed hjælper.</p><h2 id="holddynamik-under-konkurrencen" tabindex="-1">Holddynamik under konkurrencen <a class="header-anchor" href="#holddynamik-under-konkurrencen" aria-label="Permalink to &quot;Holddynamik under konkurrencen&quot;">​</a></h2><h3 id="før-kampen" tabindex="-1">Før kampen <a class="header-anchor" href="#før-kampen" aria-label="Permalink to &quot;Før kampen&quot;">​</a></h3><ul><li>Kom sammen, varm op sammen</li><li>Diskuter den generelle strategi</li><li>Sæt tonen (positiv, fokuseret)</li><li>Tjek hvordan alle har det</li></ul><h3 id="under-spillet" tabindex="-1">Under spillet <a class="header-anchor" href="#under-spillet" aria-label="Permalink to &quot;Under spillet&quot;">​</a></h3><ul><li>Kommuniker mellem enderne</li><li>Forbliv positiv uanset score</li><li>Støt hinanden efter fejltagelser</li><li>Fejr succeser sammen (kort)</li><li>Hold fokus på processen, ikke resultatet</li></ul><h3 id="efter-fejl" tabindex="-1">Efter fejl <a class="header-anchor" href="#efter-fejl" aria-label="Permalink to &quot;Efter fejl&quot;">​</a></h3><p>Hvad man IKKE skal gøre:</p><ul><li>Vis synligt frustration</li><li>Kritisere eller bebrejde</li><li>Træk dig tilbage eller bliv tavs</li><li>Dvæl ved, hvad der skete</li></ul><p>Hvad SKAL MAN GØRE:</p><ul><li>Hurtig bekræftelse (&quot;intet problem&quot;)</li><li>Flyt fokus til næste kast</li><li>Bevar et positivt kropssprog</li><li>Stol på din holdkammerat til at komme sig</li></ul><h3 id="efter-kampen" tabindex="-1">Efter kampen <a class="header-anchor" href="#efter-kampen" aria-label="Permalink to &quot;Efter kampen&quot;">​</a></h3><ul><li>Fælles debriefing (hvad virkede, hvad virkede ikke)</li><li>Anerkend individuelle bidrag</li><li>Diskuter forbedringer til næste gang</li><li>Bevar relationer uanset resultat</li></ul><h2 id="kommunikationsmønstre" tabindex="-1">Kommunikationsmønstre <a class="header-anchor" href="#kommunikationsmønstre" aria-label="Permalink to &quot;Kommunikationsmønstre&quot;">​</a></h2><h3 id="konstruktiv-feedback" tabindex="-1">Konstruktiv feedback <a class="header-anchor" href="#konstruktiv-feedback" aria-label="Permalink to &quot;Konstruktiv feedback&quot;">​</a></h3><p><strong>Dårlig:</strong> &quot;Du bliver ved med at misse de skud&quot; <strong>Bedre:</strong> &quot;Jeg bemærkede, at slagene går til venstre - vil du prøve at justere din holdning?&quot;</p><h3 id="støttende-reaktion-pa-fejl" tabindex="-1">Støttende reaktion på fejl <a class="header-anchor" href="#støttende-reaktion-pa-fejl" aria-label="Permalink to &quot;Støttende reaktion på fejl&quot;">​</a></h3><p><strong>Dårlig:</strong> <em>Tavshed eller synlig frustration</em><strong>Bedre:</strong> &quot;Svært spørgsmål. Du har den næste.&quot;</p><h3 id="strategisk-diskussion" tabindex="-1">Strategisk diskussion <a class="header-anchor" href="#strategisk-diskussion" aria-label="Permalink to &quot;Strategisk diskussion&quot;">​</a></h3><p><strong>Dårlig:</strong> &quot;Bare skyd den&quot; <strong>Bedre:</strong> &quot;Hvad synes du - at pointte for at blokere eller forsøge at skyde? Jeg ser fordele og ulemper ved begge dele.&quot;</p><h2 id="opbygning-af-teamkultur" tabindex="-1">Opbygning af teamkultur <a class="header-anchor" href="#opbygning-af-teamkultur" aria-label="Permalink to &quot;Opbygning af teamkultur&quot;">​</a></h2><p>Gode teams udvikler sig delt:</p><ul><li><strong>Værdier:</strong> Hvad vi står for</li><li><strong>Normer:</strong> Hvordan vi opfører os</li><li><strong>Sprog:</strong> Hvordan vi kommunikerer</li><li><strong>Ritualer:</strong> Hvad vi gør sammen</li></ul><p><strong>Eksempler:</strong></p><ul><li>Giv altid hånden før og efter</li><li>Specifikke opmuntrende sætninger</li><li>Fælles rutine før kampen</li><li>Måltid eller drikkevare efter kampen</li></ul><h2 id="i-dette-afsnit" tabindex="-1">I dette afsnit <a class="header-anchor" href="#i-dette-afsnit" aria-label="Permalink to &quot;I dette afsnit&quot;">​</a></h2><ul><li><strong><a href="/da/uddannelse/teamspiller/kommunikation">Teamkommunikation</a></strong> - Detaljeret guide til effektiv kommunikation</li></ul><h2 id="vigtig-konklusion" tabindex="-1">Vigtig konklusion <a class="header-anchor" href="#vigtig-konklusion" aria-label="Permalink to &quot;Vigtig konklusion&quot;">​</a></h2><blockquote><p>Dit hold er kun så stærkt som dets svageste forhold, ikke dets svageste spiller.</p></blockquote><p>Investér i dine holdkammerater. Opbyg tillid. Kommunikér godt. Vind sammen.</p>',43)),a(p)])}]]);export{k as __pageData,m as default};
